function view(id){
  document.querySelectorAll("main section").forEach(s => s.classList.add("hide"));
  const section = $(id);
  if (section) section.classList.remove("hide");
  window.scrollTo(0,0);
}


function vocabBlock(id){ return VOCAB_BLOCKS.find(b=>b.id===id); }
function blockProgress(id){ return vocabProgress.filter(x=>x.blockId===id); }
function saveVocabProgress(){ localStorage.setItem('citajSrpskiVocabProgress',JSON.stringify(vocabProgress)); }
function addVocabWord(item, blockId){
  if(!vocabProgress.some(x=>x.word===item.word && x.blockId===blockId)){
    vocabProgress.push({word:item.word,blockId,box:1,nextReview:Date.now()});
    saveVocabProgress();
  }
}
function addWholeBlock(id){
  const b=vocabBlock(id); if(!b) return;
  b.words.forEach(x=>addVocabWord(x,id));
  saveVocabProgress(); vocab();
}
function startBlockReview(id){
  const b=vocabBlock(id); if(!b) return;
  const list=blockProgress(id);
  if(!list.length){
    addWholeBlock(id);
    startBlockReview(id);
    return;
  }
  exerciseType='choice';
  exercisePool=list;
  exerciseQueue=shuffle(list).slice(0,Math.min(20,list.length)).map(x=>x.word);
  exerciseIndex=0;
  renderExercise();
  view('review');
}
function vocab(){
  $('vocab-list').innerHTML=VOCAB_BLOCKS.map(b=>{
    const count=blockProgress(b.id).length;
    return `<div class="card vocab-card">
      <div class="tag">${b.level}</div>
      <h3>${b.title}</h3>
      <p class="muted">${b.description}</p>
      <p><b>100 слов</b> · в учебном прогрессе: <b>${count}</b></p>
      <div class="vocab-actions">
        <button type="button" class="vocab-add" data-block="${b.id}">＋ Изучать весь блок</button>
        <button type="button" class="vocab-review" data-block="${b.id}">🔁 Повторять только этот блок</button>
      </div>
      <details><summary>Показать слова</summary><div class="vocab-list">${b.words.map((x,i)=>{
        const active=blockProgress(b.id).some(s=>s.word===x.word);
        return `<div class="vocab-row"><span>${i+1}. <b>${x.word}</b></span><span>${x.translation}</span><button type="button" class="vocab-one" data-block="${b.id}" data-word="${x.word}">${active?'✓':'＋'}</button></div>`;
      }).join('')}</div></details>
    </div>`;
  }).join('');
  view('vocab');
  document.querySelectorAll('.vocab-add').forEach(btn=>btn.addEventListener('click',()=>addWholeBlock(btn.dataset.block)));
  document.querySelectorAll('.vocab-review').forEach(btn=>btn.addEventListener('click',()=>startBlockReview(btn.dataset.block)));
  document.querySelectorAll('.vocab-one').forEach(btn=>btn.addEventListener('click',()=>{
    const b=vocabBlock(btn.dataset.block); const item=b?.words.find(x=>x.word===btn.dataset.word);
    if(item){addVocabWord(item,b.id);vocab();}
  }));
}

function texts(){
  const local = TEXTS.filter(t=>!t.level.includes('Исторический')).map(t=>{
    const realIndex=TEXTS.indexOf(t);
    const n=t.text.split(/[.!?]+/).filter(Boolean).length;
    return `<div class="card"><div class="tag">${t.level}</div><h3>${t.title}</h3><p>${t.ru}</p><p class="muted">Большой учебный текст · ${n} предложений</p><button type="button" class="read-text" data-index="${realIndex}">📖 Читать на сайте</button></div>`;
  }).join('');
  const historical=TEXTS.filter(t=>t.level.includes('Исторический')).map(t=>{
    const realIndex=TEXTS.indexOf(t);
    const n=t.text.split(/[.!?]+/).filter(Boolean).length;
    return `<div class="card real-source-card"><div class="tag">${t.level}</div><h3>${t.title}</h3><p>${t.ru}</p><p class="muted"><b>${n} предложений.</b> Полный оригинальный текст встроен в сайт и доступен для чтения здесь.</p><p class="source">${t.source}</p><div class="vocab-actions"><button type="button" class="read-text" data-index="${realIndex}">📖 Читать оригинал на сайте</button><a class="source-link" href="${t.url}" target="_blank" rel="noopener">Первоисточник ↗</a></div></div>`;
  }).join('');
  $('list').innerHTML=`<div class="card library-summary"><h3>Библиотека</h3><p>Сейчас доступно <b>${local.length} учебных текстов</b> и <b>${historical.length} исторических оригиналов</b>.</p><p class="muted">Все тексты открываются внутри нашего сайта. Нажимай на слова, чтобы смотреть перевод и сохранять их в «Мои слова».</p><p><b>Новые A2 в этой версии:</b> Dan na fakultetu · Subota u gradu · Mala izložba u kulturnom centru · Priprema putovanja vozom · Mali tim na poslu · Nedelja bez žurbe.</p></div><h3 class="library-heading">📚 Учебные тематические тексты A1/A2</h3>${local}<h3 class="library-heading">📜 Исторические оригинальные тексты</h3><p class="muted">Эти произведения встроены локально и открываются прямо в нашем режиме чтения.</p>${historical}`;
}

function openRealSource(i){
  const t=REAL_SOURCES[i];
  window.open(t.url,'_blank','noopener');
}

function tokenize(text){ return text.split(/(\s+)/); }

function renderText(text){
  $("text").innerHTML = tokenize(text).map(part => {
    if (/^\s+$/.test(part)) return part;
    const clean = normalize(part);
    if (!clean) return part;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "word";
    btn.dataset.word = clean;
    btn.textContent = part;
    return btn.outerHTML;
  }).join("");
}

function openText(i){
  const t = TEXTS[i];
  $("title").textContent = t.title;
  $("level").textContent = `${t.level} · ${t.ru}`;
  $("source").textContent = t.source;
  renderText(t.text);
  $("popup").classList.add("hide");
  view("reader");
}

function getSerbianVoice(){
  const voices=window.speechSynthesis.getVoices();
  return voices.find(v=>/^sr(-|_)/i.test(v.lang)) || null;
}

function speakWord(w){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  window.speechSynthesis.cancel();
  const voice=getSerbianVoice();
  if(!voice){
    alert('На этом устройстве не найден сербский голос. Я не буду подставлять английский голос, чтобы не искажать произношение. Установи/включи сербский голос в настройках синтеза речи Android, после чего кнопка будет использовать именно его.');
    return;
  }
  const u = new SpeechSynthesisUtterance(w);
  u.voice=voice;
  u.lang=voice.lang || 'sr-RS';
  u.rate=0.78;
  u.pitch=1;
  window.speechSynthesis.speak(u);
}

function speakText(text){
  if (!('speechSynthesis' in window)) {
    alert('Озвучка не поддерживается этим браузером.');
    return;
  }
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = 'sr-RS';
  u.rate = 0.88;
  window.speechSynthesis.speak(u);
}

async function word(w){
  const requestId=++translationRequestId;
  const translation = getTranslation(w);
  const exists = saved.some(x => x.word === w);
  const verb = findVerbInfo(w);
  const render = (tr, v=verb) => {
    if(requestId!==translationRequestId) return;
    const verbBlock = v ? `
      <div class="verb-block">
        <div class="verb-title">Глагол: <b>${escapeHtml(v.lemma)}</b> · ${escapeHtml(v.translation||tr)}</div>
        <div class="verb-grid">
          <div><span>Инфинитив</span><b>${escapeHtml(v.lemma)} <small>— ${escapeHtml(v.translation||tr)}</small></b></div>
          <div><span>Прошедшее</span><b>${escapeHtml(v.past||'—')}</b></div>
          <div><span>Настоящее</span><b>${escapeHtml(v.present||'—')}</b></div>
          <div><span>Будущее</span><b>${escapeHtml(v.future||('će '+v.lemma))}</b></div>
        </div>
        ${v.generated ? '<div class="verb-note">Формы построены для регулярного глагола. Для неправильных глаголов используются отдельные формы.</div>' : ''}
      </div>` : '';
    $('popup').innerHTML = `
      <div class="popup-title">${escapeHtml(w)}</div>
      <div class="popup-translation">${escapeHtml(tr)}</div>
      ${verbBlock}
      <div class="popup-actions">
        <button type="button" id="speak-word">🔊 Слушать</button>
        <button type="button" id="add-word-button">${exists ? '✓ Уже в моих словах' : 'Добавить в мои слова'}</button>
      </div>`;
    $('popup').classList.remove('hide');
    $('speak-word').addEventListener('click', () => speakWord(w));
    const addButton = $('add-word-button');
    if(addButton && !exists) addButton.addEventListener('click', () => addWord(w));
  };
  render(translation);
  if(translation === 'Перевод загружается…'){
    const tr=await remoteTranslateWord(w);
    let v=verb;
    if(v && !v.translation) v={...v,translation:tr};
    render(tr,v);
  } else if(verb && !verb.translation){
    const tr=await remoteTranslateWord(verb.lemma);
    render(translation,{...verb,translation:tr});
  }
}

function addWord(w){
  if (!saved.some(x => x.word === w)) {
    saved.push({word:w, translation:getTranslation(w), added:new Date().toISOString(), box:1, nextReview:Date.now()});
    save();
  }
  word(w);
}

function words(){
  const due = getDueWords().length;
  const blockCounts = VOCAB_BLOCKS.map(b => ({...b, count:blockProgress(b.id).length})).filter(b => b.count);
  $('saved').innerHTML = `
    <div class="card review-card">
      <h3>Тренировки</h3>
      <p>Здесь можно не только повторять слова по интервалам, но и активно вспоминать их.</p>
      <p><b>К повторению сегодня: ${due}</b></p>
      <div class="training-buttons">
        <button type="button" id="start-review">🔁 Повторить по интервалам</button>
        <button type="button" id="start-difficult">🔥 Повторить трудные</button>
        <button type="button" id="start-learning">🟡 Повторить изучаемые</button>
        <button type="button" id="start-choice">🎯 Слово → перевод</button>
        <button type="button" id="start-reverse">🧠 Перевод → слово</button>
      </div>
      <h4>Как запоминаются слова</h4>
      <p class="muted">Каждое правильное повторение переводит слово дальше: 1 → 2 → 4 → 7 → 14 → 30 дней. Ошибка возвращает его в первую коробку.</p>
      <div class="memory-stats"><span>🆕 Новые: <b>${saved.filter(x=>(Number(x.box)||1)===1).length}</b></span><span>🟡 Закрепляются: <b>${saved.filter(x=>(Number(x.box)||1)>=3 && (Number(x.box)||1)<=5).length}</b></span><span>🟢 Выучены: <b>${saved.filter(x=>(Number(x.box)||1)===6).length}</b></span></div>
      <h4>Учебные блоки — отдельно от «Моих слов»</h4>
      <p class="muted">Слова из тематических блоков не входят в «Мои слова». Они хранятся отдельно и повторяются только внутри выбранного блока.</p>
      <div class="block-buttons">${blockCounts.length ? blockCounts.map(b=>`<button type="button" class="saved-block-review" data-block="${b.id}">${b.level} · ${b.title} (${b.count}/100)</button>`).join('') : '<span class="muted">Пока нет сохранённых блоков.</span>'}</div>
      <hr>
      <button type="button" id="export-words">💾 Сохранить мои слова</button>
      <button type="button" id="import-words">📥 Загрузить мои слова</button>
      <input id="import-file" type="file" accept="application/json" class="hide">
      <p class="muted small-note">Твои слова остаются в localStorage при обычном обновлении сайта. Резервная копия нужна на случай очистки данных браузера или смены устройства.</p>
    </div>
    <div class="card">
      <h3>Мои слова: ${saved.length}</h3>
      ${saved.length ? saved.map((x,i) => `<div class="row"><b>${x.word}</b><span> — ${x.translation}</span><span class="box-label">Коробка ${x.box || 1}${x.blockId ? ' · '+(vocabBlock(x.blockId)?.id || x.blockId) : ''}</span><button type="button" class="small speak-saved" data-word="${x.word}">🔊</button><button type="button" class="small remove-word" data-index="${i}">Удалить</button></div>`).join('') : `<p>Словарь пока пуст.</p>`}
    </div>`;
  view('words');

  $('start-review').addEventListener('click', startReview);
  $('start-difficult').addEventListener('click', startDifficultReview);
  $('start-learning').addEventListener('click', startLearningReview);
  $('start-choice').addEventListener('click', () => startExercise('choice'));
  $('start-reverse').addEventListener('click', () => startExercise('reverse'));
  document.querySelectorAll('.saved-block-review').forEach(b=>b.addEventListener('click',()=>startBlockReview(b.dataset.block,'review')));
  $('export-words').addEventListener('click', exportWords);
  $('import-words').addEventListener('click', () => $('import-file').click());
  $('import-file').addEventListener('change', importWords);
  document.querySelectorAll('.speak-saved').forEach(b => b.addEventListener('click', () => speakWord(b.dataset.word)));
}

let exerciseQueue = [];
let exerciseIndex = 0;
let exerciseType = 'choice';
let exercisePool = null;

function shuffle(arr){
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }
  return a;
}

function startExercise(type){
  if (saved.length < 2) {
    alert('Для этой тренировки нужно хотя бы 2 слова в «Моих словах».');
    return;
  }
  exerciseType = type;
  exercisePool = saved;
  exerciseQueue = shuffle(saved).slice(0, Math.min(20, saved.length)).map(x => x.word);
  exerciseIndex = 0;
  renderExercise();
  view('review');
}

function renderExercise(){
  if (exerciseIndex >= exerciseQueue.length) {
    $('review-content').innerHTML = `<div class="card"><h2>Тренировка закончена 🎉</h2><p>Ты прошёл ${exerciseQueue.length} заданий.</p><button type="button" id="exercise-finish">Вернуться к моим словам</button></div>`;
    $('exercise-finish').addEventListener('click', () => { exercisePool=null; words(); });
    return;
  }
  const item = (exercisePool || saved).find(x => x.word === exerciseQueue[exerciseIndex]);
  if (!item) { exerciseIndex++; renderExercise(); return; }
  if (exerciseType === 'choice') renderChoice(item); else renderReverse(item);
}

function renderChoice(item){
  const pool = exercisePool || saved;
  const others = shuffle(pool.filter(x => x.word !== item.word)).slice(0,3);
  const options = shuffle([item, ...others]);
  $('review-content').innerHTML = `<div class="card review-card"><p class="muted">Слово → перевод · ${exerciseIndex+1} из ${exerciseQueue.length}</p><div class="flash-word">${item.word}</div><button type="button" id="exercise-speak">🔊 Послушать</button><div class="options">${options.map((x,i)=>`<button type="button" class="option" data-answer="${i}">${x.translation}</button>`).join('')}</div><div id="exercise-feedback" class="feedback"></div></div>`;
  $('exercise-speak').addEventListener('click',()=>speakWord(item.word));
  document.querySelectorAll('.option').forEach((b,i)=>b.addEventListener('click',()=>{
    const chosen=options[i]; const ok=chosen.word===item.word;
    document.querySelectorAll('.option').forEach(x=>x.disabled=true);
    $('exercise-feedback').innerHTML=ok ? '<b>✓ Правильно</b>' : `<b>✗ Не совсем.</b> Правильный ответ: ${item.translation}`;
    if(ok){ item.box=Math.min(6,(Number(item.box)||1)+1); item.nextReview=Date.now()+REVIEW_INTERVALS[item.box]*24*60*60*1000; if(item.blockId) saveVocabProgress(); else save(); }
    if(!ok){ item.box=1; item.nextReview=Date.now(); if(item.blockId) saveVocabProgress(); else save(); }
    setTimeout(()=>{exerciseIndex++; renderExercise();}, 850);
  }));
}

function renderReverse(item){
  const pool = exercisePool || saved;
  const others = shuffle(pool.filter(x => x.word !== item.word)).slice(0,3);
  const options = shuffle([item, ...others]);
  $('review-content').innerHTML = `<div class="card review-card"><p class="muted">Перевод → слово · ${exerciseIndex+1} из ${exerciseQueue.length}</p><div class="flash-word">${item.translation}</div><div class="options">${options.map((x,i)=>`<button type="button" class="option" data-answer="${i}">${x.word}</button>`).join('')}</div><div id="exercise-feedback" class="feedback"></div></div>`;
  document.querySelectorAll('.option').forEach((b,i)=>b.addEventListener('click',()=>{
    const chosen=options[i]; const ok=chosen.word===item.word;
    document.querySelectorAll('.option').forEach(x=>x.disabled=true);
    $('exercise-feedback').innerHTML=ok ? '<b>✓ Правильно</b>' : `<b>✗ Правильный ответ: ${item.word}</b>`;
    if(!ok){ item.box=1; item.nextReview=Date.now(); if(item.blockId) saveVocabProgress(); else save(); }
    setTimeout(()=>{exerciseIndex++; renderExercise();}, 850);
  }));
}

function getDueWords(){
  const now = Date.now();
  return saved.filter(x => !x.nextReview || x.nextReview <= now);
}

let reviewQueue = [];
let reviewIndex = 0;
let reviewRevealed = false;

function startReviewWithList(list, emptyMessage='Подходящих слов для этой тренировки пока нет.') {
  reviewQueue = shuffle(list).slice(0, Math.min(30, list.length)).map(x => x.word);
  reviewIndex = 0;
  reviewRevealed = false;
  if (!reviewQueue.length) { alert(emptyMessage); return; }
  renderReviewCard();
  view('review');
}

function startReview(){
  startReviewWithList(getDueWords(), 'На сегодня слов для повторения нет. Добавь новые слова или возвращайся позже.');
}

function startDifficultReview(){
  startReviewWithList(saved.filter(x => (Number(x.box)||1) <= 2), 'Сейчас нет слов в первых двух коробках.');
}

function startLearningReview(){
  startReviewWithList(saved.filter(x => (Number(x.box)||1) >= 3 && (Number(x.box)||1) <= 5), 'Сейчас нет слов в стадии закрепления.');
}

function renderReviewCard(){
  if (reviewIndex >= reviewQueue.length) {
    $('review-content').innerHTML = `<div class="card"><h2>Повторение закончено 🎉</h2><p>Ты прошёл ${reviewQueue.length} карточек.</p><button type="button" id="review-finish">Вернуться к моим словам</button></div>`;
    $('review-finish').addEventListener('click', words);
    return;
  }
  const w = reviewQueue[reviewIndex];
  const item = saved.find(x => x.word === w);
  if (!item) { reviewIndex++; renderReviewCard(); return; }
  reviewRevealed = false;
  $('review-content').innerHTML = `
    <div class="card review-card">
      <p class="muted">Карточка ${reviewIndex+1} из ${reviewQueue.length} · коробка ${item.box || 1}</p>
      <div class="flash-word">${item.word}</div>
      <div id="review-answer" class="review-answer hide">${item.translation}</div>
      <button type="button" id="show-answer">Показать перевод</button>
      <div id="review-actions" class="hide review-actions">
        <button type="button" id="forgot">Не помню</button>
        <button type="button" id="remember">Помню</button>
      </div>
    </div>`;
  $('show-answer').addEventListener('click', () => {
    reviewRevealed = true;
    $('review-answer').classList.remove('hide');
    $('show-answer').classList.add('hide');
    $('review-actions').classList.remove('hide');
  });
  $('forgot').addEventListener('click', () => answerReview(item.word, false));
  $('remember').addEventListener('click', () => answerReview(item.word, true));
}

function answerReview(w, correct){
  const item = saved.find(x => x.word === w);
  if (!item) { reviewIndex++; renderReviewCard(); return; }
  const current = Number(item.box) || 1;
  if (correct) {
    item.box = Math.min(6, current + 1);
    const days = REVIEW_INTERVALS[item.box];
    item.nextReview = Date.now() + days * 24 * 60 * 60 * 1000;
  } else {
    item.box = 1;
    item.nextReview = Date.now();
    // Ошибочные карточки ещё раз попадут в конец текущей сессии.
    reviewQueue.push(w);
  }
  save();
  reviewIndex++;
  renderReviewCard();
}

function exportWords(){
  const blob = new Blob([JSON.stringify(saved, null, 2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'citaj-srpski-moji-slova.json';
  a.click();
  URL.revokeObjectURL(url);
}

function importWords(event){
  const file = event.target.files && event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const imported = JSON.parse(reader.result);
      if (!Array.isArray(imported)) throw new Error('bad');
      const clean = imported.filter(x => x && typeof x.word === 'string').map(x => ({
        word:x.word, translation:x.translation || getTranslation(x.word),
        added:x.added || new Date().toISOString(), box:Math.min(6,Math.max(1,Number(x.box)||1)), nextReview:x.nextReview || Date.now()
      }));
      saved = clean;
      save();
      words();
      alert('Слова загружены.');
    } catch(e) { alert('Не удалось прочитать резервную копию.'); }
  };
  reader.readAsText(file);
}

function removeWord(i){
  saved.splice(i,1);
  save();
  words();
}

// Навигация — без inline onclick, чтобы сайт одинаково работал на GitHub Pages и мобильном Chrome.
document.addEventListener("click", event => {
  const popup=$('popup');
  if(!popup.classList.contains('hide') && !event.target.closest('.popup') && !event.target.closest('.word')){
    popup.classList.add('hide');
  }

  const sourceButton=event.target.closest('.read-source');
  if(sourceButton){
    openRealSource(Number(sourceButton.dataset.sourceIndex));
    return;
  }

  const nav = event.target.closest("[data-v]");
  if (nav) {
    const v = nav.dataset.v;
    if (v === "texts") texts();
    if (v === "vocab") vocab();
    if (v === "words") words();
    view(v);
    return;
  }

  const readerButton = event.target.closest(".read-text");
  if (readerButton) {
    openText(Number(readerButton.dataset.index));
    return;
  }

  const wordButton = event.target.closest(".word");
  if (wordButton) {
    word(wordButton.dataset.word);
    return;
  }

  const removeButton = event.target.closest(".remove-word");
  if (removeButton) {
    removeWord(Number(removeButton.dataset.index));
  }
});

save();
texts();
